#!/usr/bin/env bash
# Pattern: none (test). scripts/check_rust_rules.py (used by check.yml via actions/rust-rules): passes a clean tree, fails a rule break.
TR="$T/rules"; mkdir -p "$TR/src"
printf '//! Entry.\n//! Pattern: none\nfn main() {}\n' > "$TR/src/main.rs"
python3 -I "$ROOT/scripts/check_rust_rules.py" "$TR" >/dev/null && pass "rules: clean tree passes" || fail "rules: clean tree must pass"
echo 'fn main() {}' > "$TR/src/bad.rs"
python3 -I "$ROOT/scripts/check_rust_rules.py" "$TR" >/dev/null 2>&1 && fail "rules: missing module doc must fail" || pass "rules: missing module doc fails"
# Blinc in one place: only a repo with .fs-rules.toml blinc = "components-only" is checked (default off).
RR() { python3 -I "$ROOT/scripts/check_rust_rules.py" "$TR" >/dev/null 2>&1; }
ok()  { if RR; then pass "rules: $1"; else fail "rules: $1 (must pass)"; fi; }
bad() { if RR; then fail "rules: $1 (must fail)"; else pass "rules: $1"; fi; }
rm -f "$TR/src/bad.rs"
CG='git = "https://github.com/FreeSynergy/fs-components"'
printf '[package]\nname = "p"\n[dependencies]\nblinc_app = "0.6"\n[patch.crates-io]\nblinc_app = { git = "https://github.com/FreeSynergy/Blinc" }\n' > "$TR/Cargo.toml"
ok "an unmigrated repo (no .fs-rules.toml) keeps blinc and [patch] without error"
printf 'blinc = "off"\n' > "$TR/.fs-rules.toml"; ok "blinc = off checks nothing"
printf 'blinc = "maybe"\n' > "$TR/.fs-rules.toml"; bad "unknown switch value is an error"
printf 'blinc = \n' > "$TR/.fs-rules.toml"; bad "broken .fs-rules.toml is an error"
printf 'blinc = "components-only"\n' > "$TR/.fs-rules.toml"
printf '[package]\nname = "p"\n[dependencies]\nserde = "1"\n' > "$TR/Cargo.toml"; ok "migrated program without blinc passes"
printf '[package]\nname = "p"\n[dependencies]\nblinc_app = "0.6"\n' > "$TR/Cargo.toml"; bad "blinc dependency fails"
printf '[package]\nname = "p"\n[dependencies]\nx = { package = "blinc_layout", version = "0.6" }\n' > "$TR/Cargo.toml"; bad "renamed blinc dependency fails"
printf '[package]\nname = "p"\n[target."cfg(unix)".dev-dependencies]\nblinc_app = "0.6"\n' > "$TR/Cargo.toml"; bad "blinc in target dev-dependencies fails"
printf '[package]\nname = "p"\n[dependencies]\nx = { git = "https://github.com/FreeSynergy/Blinc" }\n' > "$TR/Cargo.toml"; bad "blinc by git url under another name fails"
printf '[package]\nname = "p"\n[patch.crates-io]\nblinc_app = { git = "https://github.com/FreeSynergy/Blinc", tag = "fs-blinc-1" }\n' > "$TR/Cargo.toml"; bad "blinc patch fails"
printf '[package]\nname = "p"\n[replace]\n"blinc_app:0.6.0" = { git = "https://github.com/FreeSynergy/Blinc" }\n' > "$TR/Cargo.toml"; bad "blinc [replace] fails"
printf '[package]\nname = "p"\n' > "$TR/Cargo.toml"
mkdir -p "$TR/.cargo"; printf '[patch.crates-io]\nblinc_app = { path = "../Blinc" }\n' > "$TR/.cargo/config.toml"; bad "blinc [patch] in .cargo/config.toml fails"
rm -rf "$TR/.cargo"
printf '[package]\nname = "p"\n[dependencies]\na = { %s, tag = "v0.4.0" }\n[dependencies.b]\n%s\ntag = "v0.4.0"\n' "$CG" "$CG" > "$TR/Cargo.toml"; ok "one fs-components tag everywhere passes"
mkdir -p "$TR/crates/x"; printf '[package]\nname = "x"\n[dependencies]\nc = { %s, tag = "v0.3.0" }\n' "$CG" > "$TR/crates/x/Cargo.toml"; bad "two fs-components tags in one program fail"
printf '[package]\nname = "x"\n[dependencies]\nc = { %s, rev = "abc" }\n' "$CG" > "$TR/crates/x/Cargo.toml"; bad "a tag and a rev of fs-components fail"
rm -rf "$TR/crates"
# false alarms: Cargo.toml in nested worktrees and target/ do not count
mkdir -p "$TR/.wt-old" "$TR/target/pkg"; printf '[package]\nname = "o"\n[dependencies]\nblinc_app = "1"\n' | tee "$TR/.wt-old/Cargo.toml" > "$TR/target/pkg/Cargo.toml"
ok "Cargo.toml in .wt-* and target/ are ignored"
rm -rf "$TR/.wt-old" "$TR/target"
# fs-components itself may carry blinc; an empty or foreign Cargo.toml at that path is not enough
printf '[package]\nname = "p"\n[dependencies]\nblinc_app = "0.6"\n' > "$TR/Cargo.toml"
mkdir -p "$TR/crates/fs-components"; : > "$TR/crates/fs-components/Cargo.toml"; bad "an empty crates/fs-components/Cargo.toml is no exemption"
printf '[package]\nname = "other"\n' > "$TR/crates/fs-components/Cargo.toml"; bad "a crate with another name at that path is no exemption"
printf '[package]\nname = "fs-components"\nrepository = "https://github.com/someone/else"\n' > "$TR/crates/fs-components/Cargo.toml"; bad "a foreign repository url is no exemption"
printf '[package]\nname = "fs-components"\nrepository = "https://github.com/FreeSynergy/fs-components"\n' > "$TR/crates/fs-components/Cargo.toml"; ok "the real fs-components crate may carry blinc"
printf '[package]\nname = "fs-components"\nrepository = "https://github.com/FreeSynergy-Net/fs-components"\n' > "$TR/crates/fs-components/Cargo.toml"; ok "the -Net repository url of fs-components is exempt too"
printf '[package]\nname = "fs-components"\n' > "$TR/crates/fs-components/Cargo.toml"; bad "a self-made fs-components crate without repository/origin is no exemption"
printf '[package]\nname = "fs-components"\n' > "$TR/crates/fs-components/Cargo.toml"
git init -q "$TR"; git -C "$TR" remote add origin https://github.com/FreeSynergy/fs-components.git; ok "no repository but the git origin is FreeSynergy/fs-components: exempt"
git -C "$TR" remote set-url origin https://github.com/someone/fs-components.git; bad "a fork as origin is no exemption"
rm -rf "$TR/.git"
rm -rf "$TR/crates"
# [patch]/[replace] on fs-components or blinc: forbidden in any form, also .cargo
printf '[package]\nname = "p"\n[patch."https://github.com/FreeSynergy/fs-components"]\nfs-components = { path = "../fs-components" }\n' > "$TR/Cargo.toml"; bad "a path [patch] on fs-components fails"
printf '[package]\nname = "p"\n[patch."https://github.com/FreeSynergy/fs-components"]\nfs-components = { branch = "x", git = "https://example.org/y" }\n' > "$TR/Cargo.toml"; bad "a git [patch] on fs-components fails"
printf '[package]\nname = "p"\n[replace]\n"fs-components:0.1.0" = { path = "../c" }\n' > "$TR/Cargo.toml"; bad "a [replace] on fs-components fails"
printf '[package]\nname = "p"\n[patch.crates-io]\nserde = { path = "../serde" }\n' > "$TR/Cargo.toml"; ok "a [patch] on an unrelated crate passes"
printf '[package]\nname = "p"\n' > "$TR/Cargo.toml"; mkdir -p "$TR/.cargo"
printf '[patch."https://github.com/FreeSynergy/fs-components"]\nfs-components = { path = "../c" }\n' > "$TR/.cargo/config"; bad ".cargo/config [patch] on fs-components fails"
printf 'paths = ["../fs-components"]\n' > "$TR/.cargo/config.toml"; rm "$TR/.cargo/config"; bad ".cargo/config.toml paths fails"
printf '[source.fsc]\ngit = "https://github.com/FreeSynergy/fs-components"\nreplace-with = "mine"\n[source.mine]\ndirectory = "x"\n' > "$TR/.cargo/config.toml"; bad ".cargo/config.toml [source] naming fs-components fails"
printf '[source.crates-io]\nreplace-with = "vendored"\n[source.vendored]\ndirectory = "vendor"\n' > "$TR/.cargo/config.toml"; ok ".cargo/config.toml vendoring passes"
rm -rf "$TR/.cargo"
# the git url must be exactly the FreeSynergy repo: a fork with the same tag is refused
printf '[package]\nname = "p"\n[dependencies]\na = { git = "https://github.com/evil/fs-components", tag = "v0.4.0" }\n' > "$TR/Cargo.toml"; bad "a fork of fs-components with the same tag fails"
printf '[package]\nname = "p"\n[dependencies]\na = { git = "https://github.com/FreeSynergy/fs-components.git", tag = "v0.4.0" }\n' > "$TR/Cargo.toml"; ok "the official git url (.git suffix) passes"
rm -rf "$TR/Cargo.toml" "$TR/.fs-rules.toml"
# fs-components by NAME or package must be the official git url with a tag: no path, registry, other url, rev, branch
printf 'blinc = "components-only"\n' > "$TR/.fs-rules.toml"
FSC='fs-components = { git = "https://github.com/FreeSynergy/fs-components", tag = "v0.4.0" }'
printf '[package]\nname = "p"\n[dependencies]\n%s\n' "$FSC" > "$TR/Cargo.toml"; ok "fs-components by official url and tag passes"
printf '[package]\nname = "p"\n[dependencies]\nfs-components = { git = "https://www.github.com/FreeSynergy/fs-components.git", tag = "v0.4.0" }\n' > "$TR/Cargo.toml"; ok "www. and .git variants of the official url pass"
printf '[package]\nname = "p"\n[dependencies]\nfs-components = { git = "https://github.com/evil/fsc", tag = "v0.4.0" }\n' > "$TR/Cargo.toml"; bad "fs-components from a differently named fork fails"
printf '[package]\nname = "p"\n[dependencies]\nfs-components = { path = "vendor/x" }\n' > "$TR/Cargo.toml"; bad "fs-components by path fails"
printf '[package]\nname = "p"\n[dependencies]\nfs-components = "0.4"\n' > "$TR/Cargo.toml"; bad "fs-components from the registry fails"
printf '[package]\nname = "p"\n[dependencies]\nx = { package = "fs-components", version = "0.4" }\n' > "$TR/Cargo.toml"; bad "package = fs-components from the registry fails"
printf '[package]\nname = "p"\n[dependencies]\nfs-components = { git = "https://github.com/FreeSynergy-Net/fs-components", rev = "06a77a6a" }\n' > "$TR/Cargo.toml"; ok "fs-components by the -Net url and a rev passes (bundles are pinned by rev, ADR bundling)"
printf '[package]\nname = "p"\n[dependencies]\nfs-components = { git = "https://github.com/FreeSynergy/fs-components", branch = "main" }\n' > "$TR/Cargo.toml"; bad "fs-components without a tag fails"
printf '[package]\nname = "p"\n[dependencies]\nfs-components = { git = "https://github.com/FreeSynergy-Net-evil/fs-components", rev = "06a77a6a" }\n' > "$TR/Cargo.toml"; bad "a -Net-evil fork with a rev fails"
mkdir -p "$TR/crates/y"; printf '[package]\nname = "p"\n[dependencies]\nfs-components = { git = "https://github.com/FreeSynergy-Net/fs-components", rev = "06a77a6a" }\n' > "$TR/Cargo.toml"; printf '[package]\nname = "y"\n[dependencies]\nfs-components = { git = "https://github.com/FreeSynergy/fs-components", rev = "06a77a6a" }\n' > "$TR/crates/y/Cargo.toml"; bad "the same rev under both org urls is two sources for cargo and fails"; rm -rf "$TR/crates/y"
printf '[package]\nname = "p"\n[dependencies]\nfs-components = { git = "https://github.com/FreeSynergy/fs-components", rev = "main" }\n' > "$TR/Cargo.toml"; bad "rev = a branch name fails (rev must be a commit hex)"
printf '[package]\nname = "p"\n[dependencies]\nx = { git = "https://github.com/FreeSynergy/fs-components", branch = "main" }\n' > "$TR/Cargo.toml"; bad "another dependency name on the fs-components url with a branch fails"
# cargo config: `include` is followed
mkdir -p "$TR/.cargo"; printf '[package]\nname = "p"\n' > "$TR/Cargo.toml"
printf 'include = "extra.toml"\n' > "$TR/.cargo/config.toml"; printf '[patch."https://github.com/FreeSynergy/fs-components"]\nfs-components = { path = "../c" }\n' > "$TR/.cargo/extra.toml"; bad "a patch in an included cargo config fails"
printf 'include = [{ path = "extra.toml", optional = true }]\n' > "$TR/.cargo/config.toml"; bad "a patch in an include with a table form fails"
rm -rf "$TR/.cargo" "$TR/Cargo.toml" "$TR/.fs-rules.toml"
# origin decides over `repository`
printf 'blinc = "components-only"\n' > "$TR/.fs-rules.toml"; printf '[package]\nname = "p"\n[dependencies]\nblinc_app = "1"\n' > "$TR/Cargo.toml"
mkdir -p "$TR/crates/fs-components"; printf '[package]\nname = "fs-components"\nrepository = "https://github.com/FreeSynergy/fs-components"\n' > "$TR/crates/fs-components/Cargo.toml"
git init -q "$TR"; git -C "$TR" remote add origin https://github.com/someone/fs-components.git; bad "a fork origin beats a claimed official repository"
rm -rf "$TR/.git" "$TR/crates" "$TR/Cargo.toml" "$TR/.fs-rules.toml"
# Frozen folder: ONLY the Pattern rule is skipped, ONLY with a checked-in locks/<name>.sha256 whose ordner exists and whose hash matches.
rm -rf "$TR/crates" "$TR/locks" "$TR/.cargo" "$TR/Cargo.toml" "$TR/.fs-rules.toml"
D="$TR/src/dummy_v1"; mkdir -p "$D" "$TR/locks"
printf '//! Entry.\n//! Pattern: none\nfn main() {}\n' > "$TR/src/main.rs"
printf '//! Old module without a pattern line.\npub fn x() {}\n' > "$D/a.rs"
# the procedure of tools/hash-ordner.sh (per file "<relpath>\0<sha256>\n", sorted, LC_ALL=C), here for the dummy folder
hash_dir() { ( export LC_ALL=C; cd "$1" || exit 1; find . -type f -printf '%P\0' | sort -z | while IFS= read -r -d '' f; do printf '%s\0%s\n' "$f" "$(sha256sum -- "$f" | cut -d' ' -f1)"; done | sha256sum | cut -d' ' -f1 ); }
lock() { printf '# lock\nordner: %s\nsha256: %s\n' "$1" "$2" > "$TR/locks/$3.sha256"; }
H="$(hash_dir "$D")"
bad "frozen folder: no lock file, Pattern rule applies"
lock src/dummy_v1 "$H" dummy_v1; ok "frozen folder: valid lock + matching hash is exempt"
lock src/dummy_v1 "0${H#?}" dummy_v1; bad "frozen folder: wrong hash, rule applies"
lock src/dummy_v1 "$H" dummy_v1; printf '//! New.\npub fn y() {}\n' > "$D/b.rs"; bad "frozen folder: new file after locking breaks the hash"
rm "$D/b.rs"; ok "frozen folder: change reverted, exempt again"
printf '//! Old module without a pattern line.\npub fn x() {} // edit\n' > "$D/a.rs"; bad "frozen folder: edited file breaks the hash"
printf '//! Old module without a pattern line.\npub fn x() {}\n' > "$D/a.rs"
rm "$TR/locks/dummy_v1.sha256"; lock src/dummy_v1 "$H" other_name; bad "frozen folder: lock file with another folder name is no exemption"
rm "$TR/locks/other_name.sha256"; lock src/dummy_v1 "$H" dummy_v1
printf '//! Outside.\npub fn z() {}\n' > "$TR/src/outside.rs"; bad "frozen folder: a file outside it is not exempt"
rm "$TR/src/outside.rs"
printf '//! Entry.\n' > "$D/c.rs"; H2="$(hash_dir "$D")"; lock src/dummy_v1 "$H2" dummy_v1; ok "frozen folder: other rules stay (module doc present, Pattern skipped)"
printf 'pub fn q() {}\n' > "$D/c.rs"; lock src/dummy_v1 "$(hash_dir "$D")" dummy_v1; bad "frozen folder: a missing //! module doc is still an error"
rm -rf "$TR/locks" "$D"
